SELECT n.*, CASE WHEN TIMESTAMPDIFF(MINUTE, n.created_at, NOW()) < 1 THEN '방금 전' WHEN TIMESTAMPDIFF(MINUTE, n.created_at, NOW()) < 60 THEN CONCAT(TIMESTAMPDIFF(MINUTE, n.created_at, NOW()), '분 전') WHEN TIMESTAMPDIFF(HOUR, n.created_at, NOW()) < 24 THEN CONCAT(TIMESTAMPDIFF(HOUR, n.created_at, NOW()), '시간 전') WHEN TIMESTAMPDIFF(DAY, n.created_at, NOW()) = 1 THEN '어제' ELSE DATE_FORMAT(n.created_at, '%m/%d') END AS created_at_label FROM notification n WHERE n.member_name IN ( SELECT DISTINCT l.member_name FROM lesson l WHERE l.lesson_date = #{today} )
AND n.member_name = #{memberName}
ORDER BY n.created_at DESC LIMIT #{limit}

